-- Domande frequenti: categorie e domande gestite dalla dashboard (Setup > Domande frequenti).
-- Le categorie collegate a un prodotto (product_slug) compaiono anche nella pagina di quel prodotto.
create table if not exists public.faq_categories (
  id           uuid primary key default gen_random_uuid(),
  slug         text not null unique,
  name         text not null,
  product_slug text,                                  -- es. adesivi_resinati: la categoria vale anche per quella pagina prodotto
  sort         int not null default 0,
  active       boolean not null default true,
  created_at   timestamptz not null default now()
);
create table if not exists public.faq_items (
  id           uuid primary key default gen_random_uuid(),
  category_id  uuid not null references public.faq_categories(id) on delete cascade,
  q            text not null,
  a            text not null,
  sort         int not null default 0,
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists faq_items_cat_idx on public.faq_items (category_id, sort);
alter table public.faq_categories enable row level security;
alter table public.faq_items enable row level security;
drop policy if exists "faq cat: public read" on public.faq_categories;
create policy "faq cat: public read" on public.faq_categories for select using (active = true or public.is_staff());
drop policy if exists "faq cat: staff all" on public.faq_categories;
create policy "faq cat: staff all" on public.faq_categories for all using (public.is_staff()) with check (public.is_staff());
drop policy if exists "faq items: public read" on public.faq_items;
create policy "faq items: public read" on public.faq_items for select using (active = true or public.is_staff());
drop policy if exists "faq items: staff all" on public.faq_items;
create policy "faq items: staff all" on public.faq_items for all using (public.is_staff()) with check (public.is_staff());

